import collections
import functools
import types

def lru_cache(maxsize=128, typed=False):
    if maxsize is not None:
        if maxsize < 0:
            raise ValueError("maxsize must be >= 0 or None")
    def decorating_function(user_function):
        cache = collections.OrderedDict()
        hits = misses = 0
        @functools.wraps(user_function)
        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            try:
                if kwargs:
                    key = args + tuple(sorted(kwargs.items()))
                else:
                    key = args
                if typed:
                    key = key + tuple(type(v) for v in args)
                    if kwargs:
                        key = key + tuple(type(v) for k, v in sorted(kwargs.items()))
                if key in cache:
                    cache.move_to_end(key)
                    hits += 1
                    return cache[key]
                result = user_function(*args, **kwargs)
                if maxsize is not None:
                    if len(cache) >= maxsize:
                        cache.popitem(last=False)
                cache[key] = result
                misses += 1
                return result
            except TypeError:
                # unhashable arguments: fallback to direct call
                return user_function(*args, **kwargs)
        def cache_clear():
            nonlocal hits, misses
            cache.clear()
            hits = misses = 0
        wrapper.cache_clear = cache_clear
        wrapper.cache_info = lambda: types.SimpleNamespace(hits=hits, misses=misses, maxsize=maxsize, currsize=len(cache))

